-- check.sql — self-check for: PE SP26-1 — Q1, Q8, Q9: ERD → tables (nvarchar), procedure with OUTPUT, AFTER INSERT trigger
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 6 checks ──────────';

-- CHECK 1: Q1 · the four entity tables with the ERD columns and nvarchar lengths
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF(EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Building'') AND c.name = N''BuildingID'' AND t.name = N''int'') AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Building'') AND c.name = N''BuildingName'' AND t.name = N''nvarchar'' AND c.max_length = 200) AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Floor'') AND c.name = N''FloorName'' AND t.name = N''nvarchar'' AND c.max_length = 200) AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Floor'') AND c.name = N''ApartmentCount'' AND t.name = N''int'')
  AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Equipment'') AND c.name = N''Description'' AND t.name = N''nvarchar'' AND c.max_length = 510) AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Manufacturer'') AND c.name = N''Address'' AND t.name = N''nvarchar'' AND c.max_length = 510) AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Manufacturer'') AND c.name = N''ManufacturerName'' AND t.name = N''nvarchar'' AND c.max_length = 200), 1, 0);
SET @info = N''expected Building/Floor/Equipment/Manufacturer exactly as the ERD (nvarchar lengths included)'';',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. Q1 · the four entity tables with the ERD columns and nvarchar lengths | Q1 · bốn bảng thực thể với đúng cột và độ dài nvarchar của ERD'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. Q1 · the four entity tables with the ERD columns and nvarchar lengths | Q1 · bốn bảng thực thể với đúng cột và độ dài nvarchar của ERD', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: Q1 · two 1–N foreign keys (Floor.BuildingID, Equipment.ManufacturerID)
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF(EXISTS (SELECT 1 FROM sys.foreign_key_columns f JOIN sys.columns c ON c.object_id = f.parent_object_id AND c.column_id = f.parent_column_id WHERE f.parent_object_id = OBJECT_ID(N''dbo.Floor'') AND c.name = N''BuildingID'' AND f.referenced_object_id = OBJECT_ID(N''dbo.Building''))
  AND EXISTS (SELECT 1 FROM sys.foreign_key_columns f JOIN sys.columns c ON c.object_id = f.parent_object_id AND c.column_id = f.parent_column_id WHERE f.parent_object_id = OBJECT_ID(N''dbo.Equipment'') AND c.name = N''ManufacturerID'' AND f.referenced_object_id = OBJECT_ID(N''dbo.Manufacturer'')), 1, 0);
SET @info = N''FK on the N side of each 1–N relationship'';',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. Q1 · two 1–N foreign keys (Floor.BuildingID, Equipment.ManufacturerID) | Q1 · hai khoá ngoại 1–N (Floor.BuildingID, Equipment.ManufacturerID)'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. Q1 · two 1–N foreign keys (Floor.BuildingID, Equipment.ManufacturerID) | Q1 · hai khoá ngoại 1–N (Floor.BuildingID, Equipment.ManufacturerID)', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: Q1 · setup_Equi: composite PK (FloorID, EquipmentID), two FKs, Quantity int
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF((SELECT COUNT(*) FROM sys.index_columns ic JOIN sys.indexes i ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.object_id = OBJECT_ID(N''dbo.setup_Equi'') AND i.is_primary_key = 1) = 2
  AND (SELECT COUNT(*) FROM sys.foreign_keys WHERE parent_object_id = OBJECT_ID(N''dbo.setup_Equi'')) = 2 AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.setup_Equi'') AND c.name = N''Quantity'' AND t.name = N''int''), 1, 0);
SET @info = N''expected PRIMARY KEY (FloorID, EquipmentID), FKs to Floor and Equipment, Quantity int'';',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. Q1 · setup_Equi: composite PK (FloorID, EquipmentID), two FKs, Quantity int | Q1 · setup_Equi: khoá chính ghép (FloorID, EquipmentID), hai khoá ngoại, Quantity int'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. Q1 · setup_Equi: composite PK (FloorID, EquipmentID), two FKs, Quantity int | Q1 · setup_Equi: khoá chính ghép (FloorID, EquipmentID), hai khoá ngoại, Quantity int', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 4: Q8 · 'UK' → 2, 'VN' → 0, 'US' → the real count
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @uk INT, @vn INT, @us INT;
EXEC prNumberOfDepartments ''UK'', @uk OUTPUT; EXEC prNumberOfDepartments ''VN'', @vn OUTPUT; EXEC prNumberOfDepartments ''US'', @us OUTPUT;
SET @ok = IIF(@uk = 2 AND @vn = 0 AND @us = (SELECT COUNT(*) FROM Departments d JOIN Locations l ON l.LocationID = d.LocationID WHERE l.CountryID = ''US''), 1, 0);
SET @info = CONCAT(N''UK = '', @uk, N'', VN = '', COALESCE(CAST(@vn AS NVARCHAR(10)), N''NULL''), N'', US = '', @us);',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 4. Q8 · ''UK'' → 2, ''VN'' → 0, ''US'' → the real count | Q8 · ''UK'' → 2, ''VN'' → 0, ''US'' → số đếm thật'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 4. Q8 · ''UK'' → 2, ''VN'' → 0, ''US'' → the real count | Q8 · ''UK'' → 2, ''VN'' → 0, ''US'' → số đếm thật', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 5: Q9 · inserting employee 1003 displays 1003, Eee, Ggg, 50, Shipping
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @r TABLE (EmployeeID INT, FirstName VARCHAR(30), LastName VARCHAR(30), DepartmentID INT, DepartmentName VARCHAR(50));
BEGIN TRAN;
INSERT INTO @r EXEC (N''insert into Employees(EmployeeID,FirstName,LastName,Email,JobID,DepartmentID) values (1003,''''Eee'''',''''Ggg'''',''''eee.ggg@gmail.com'''',''''SH_CLERK'''',50)'');
IF @@TRANCOUNT > 0 ROLLBACK;
SET @ok = IIF((SELECT COUNT(*) FROM @r) = 1 AND EXISTS (SELECT 1 FROM @r WHERE EmployeeID = 1003 AND DepartmentID = 50 AND DepartmentName = ''Shipping''), 1, 0);
SET @info = CONCAT(N''rows displayed: '', (SELECT COUNT(*) FROM @r));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 5. Q9 · inserting employee 1003 displays 1003, Eee, Ggg, 50, Shipping | Q9 · chèn nhân viên 1003 hiện 1003, Eee, Ggg, 50, Shipping'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 5. Q9 · inserting employee 1003 displays 1003, Eee, Ggg, 50, Shipping | Q9 · chèn nhân viên 1003 hiện 1003, Eee, Ggg, 50, Shipping', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 6: Q9 · one INSERT of two employees displays both rows
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @r TABLE (EmployeeID INT, FirstName VARCHAR(30), LastName VARCHAR(30), DepartmentID INT, DepartmentName VARCHAR(50));
BEGIN TRAN;
INSERT INTO @r EXEC (N''insert into Employees(EmployeeID,FirstName,LastName,Email,JobID,DepartmentID) values (1004,''''A'''',''''B'''',''''a@b'''',''''IT_PROG'''',60), (1005,''''C'''',''''D'''',''''c@d'''',''''SA_REP'''',80)'');
IF @@TRANCOUNT > 0 ROLLBACK;
SET @ok = IIF((SELECT COUNT(*) FROM @r) = 2 AND EXISTS (SELECT 1 FROM @r WHERE EmployeeID = 1004 AND DepartmentName = ''IT'') AND EXISTS (SELECT 1 FROM @r WHERE EmployeeID = 1005 AND DepartmentName = ''Sales''), 1, 0);
SET @info = CONCAT(N''rows displayed: '', (SELECT COUNT(*) FROM @r), N'' (expected 2)'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 6. Q9 · one INSERT of two employees displays both rows | Q9 · một lệnh INSERT hai nhân viên hiện cả hai dòng'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 6. Q9 · one INSERT of two employees displays both rows | Q9 · một lệnh INSERT hai nhân viên hiện cả hai dòng', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

PRINT N'──────────────────────────────────────';
IF @fail = 0 PRINT CONCAT(N'ALL ', @pass, N' CHECKS PASSED — go back to Code Lab and press "Mark as solved".');
ELSE PRINT CONCAT(@pass, N' passed, ', @fail, N' FAILED — fix solution.sql, then run setup.sql, solution.sql, check.sql again.');
SELECT CASE WHEN @fail = 0 THEN N'ALL CHECKS PASSED' ELSE N'NOT YET' END AS Result, @pass AS Passed, @fail AS Failed;
IF @fail > 0 RAISERROR(N'%d check(s) failed', 16, 1, @fail);

